WITH cleaned AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, CONCAT(firmware, ', ', device_code) firmware_device_code, temp_c * pressure temp_c_times_pressure FROM device_readings WHERE device_code IN ('DV-04', 'DV-02', 'DV-03')) SELECT firmware, device_code FROM cleaned INTERSECT SELECT firmware, device_code FROM device_readings WHERE firmware IN ('1.0.3', '2.0.1', '1.1.0')
